```csharp
using System;
using System.Text.Json;

namespace JsonSerializationExample
{
    // 1. Veri modelini tanımlıyoruz
    public class User
    {
        public int Id { get; set; }
        public string FullName { get; set; }
        public string Email { get; set; }
        public bool IsActive { get; set; }
    }

    class Program
    {
        static void Main(string[] args)
        {
            // 2. Örnek bir nesne oluşturuyoruz
            var user = new User
            {
                Id = 101,
                FullName = "Doğuş Yılmaz",
                Email = "dogus@example.com",
                IsActive = true
            };

            // 3. JSON çıktı ayarlarını yapılandırıyoruz (Okunabilir olması için)
            var options = new JsonSerializerOptions
            {
                WriteIndented = true, // Çıktıyı formatlı (girintili) yazar
                PropertyNamingPolicy = JsonNamingPolicy.CamelCase // Özellik isimlerini camelCase yapar
            };

            try
            {
                // 4. Serileştirme işlemi
                string jsonString = JsonSerializer.Serialize(user, options);

                Console.WriteLine("Serileştirilmiş JSON:");
                Console.WriteLine(jsonString);
            }
            catch (JsonException ex)
            {
                Console.WriteLine($"JSON Serileştirme Hatası: {ex.Message}");
            }
        }
    }
}
```

